def magic_square_test(my_matrix):
    n = len(my_matrix)
    for i in range(n):
        if my_matrix[i][i] == 0:
            return False
        if i % 2 == 0:
            my_matrix[i][n - 1 - i] = my_matrix[i][0]
        else:
            my_matrix[i][n - 1 - i] = my_matrix[n - 1 - i][0]
    return True
